function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Graph' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with Graph(n, edges).';
  const [n, edges] = args[0];
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (!Array.isArray(edges) || edges.length > n * (n - 1)) return 'edges has at most n * (n - 1) entries.';
  const seen = new Set();
  const bad = (edge) => {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each edge is [from, to, edgeCost].';
    const [from, to, cost] = edge;
    if (from < 0 || from >= n || to < 0 || to >= n) return 'Edge endpoints are between 0 and n - 1.';
    if (cost < 1 || cost > 1000000) return 'Edge costs are between 1 and 10^6.';
    if (from === to) return 'The graph has no self-loops.';
    if (seen.has(from * n + to)) return 'The graph never has two edges with the same from and to.';
    seen.add(from * n + to);
    return null;
  };
  for (const edge of edges) {
    const message = bad(edge);
    if (message) return message;
  }
  let adds = 0;
  let queries = 0;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'addEdge') {
      if (++adds > 100) return 'At most 100 calls to addEdge.';
      if (a.length !== 1) return 'addEdge takes one edge.';
      const message = bad(a[0]);
      if (message) return message;
    } else if (operations[i] === 'shortestPath') {
      if (++queries > 100) return 'At most 100 calls to shortestPath.';
      if (a.length !== 2 || !a.every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'node1 and node2 are between 0 and n - 1.';
    } else {
      return 'Only addEdge and shortestPath can follow the constructor.';
    }
  }
  return null;
}

