class Graph {
  constructor(n, edges) {
    this.n = n;
    this.adj = Array.from({ length: n }, () => []);
    for (const edge of edges) {
      this.addEdge(edge);
    }
  }

  addEdge(edge) {
    const [from, to, cost] = edge;
    this.adj[from].push([to, cost]);
  }

  shortestPath(node1, node2) {
    const dist = new Array(this.n).fill(Infinity);
    const done = new Array(this.n).fill(false);
    dist[node1] = 0;
    for (let round = 0; round < this.n; round++) {
      let node = -1;
      for (let v = 0; v < this.n; v++) {
        if (!done[v] && (node === -1 || dist[v] < dist[node])) {
          node = v;
        }
      }
      if (dist[node] === Infinity) {
        return -1;
      }
      if (node === node2) {
        return dist[node];
      }
      done[node] = true;
      for (const [next, cost] of this.adj[node]) {
        if (dist[node] + cost < dist[next]) {
          dist[next] = dist[node] + cost;
        }
      }
    }
    return -1;
  }
}

