class Graph {
  constructor(n, edges) {
    this.n = n;
    this.edges = edges.map(edge => edge.slice());
  }
  addEdge(edge) {
    this.edges.push(edge.slice());
  }
  shortestPath(node1, node2) {
    // Bellman-Ford: n - 1 rounds of relaxing every edge.
    const best = new Array(this.n).fill(null);
    best[node1] = 0;
    for (let round = 1; round < this.n; round++) {
      for (const [from, to, cost] of this.edges) {
        if (best[from] !== null && (best[to] === null || best[from] + cost < best[to])) best[to] = best[from] + cost;
      }
    }
    return best[node2] === null ? -1 : best[node2];
  }
}

