function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(60, 100) : int(1, 6);
  const possible = n * (n - 1);
  const top = rand() < 0.5 ? 1000000 : large ? int(1, 100) : int(1, 6);
  const used = new Set();
  const fresh = () => {
    if (used.size >= possible) return null;
    for (;;) {
      const from = int(0, n - 1);
      const to = int(0, n - 1);
      if (from === to || used.has(from * n + to)) continue;
      used.add(from * n + to);
      return [from, to, int(1, top)];
    }
  };
  const startCount = large ? (rand() < 0.4 ? int(n, 3 * n) : int(500, 1800)) : int(0, possible);
  const edges = [];
  for (let i = 0; i < startCount; i++) edges.push(fresh());
  const operations = ['Graph'];
  const args = [[n, edges]];
  let adds = large ? 100 : int(0, 4);
  let queries = large ? 100 : int(1, 6);
  while (adds + queries > 0) {
    if (adds > 0 && (queries === 0 || rand() < adds / (adds + queries))) {
      adds--;
      const edge = fresh();
      if (edge === null) continue;
      operations.push('addEdge');
      args.push([edge]);
    } else {
      queries--;
      operations.push('shortestPath');
      args.push([int(0, n - 1), int(0, n - 1)]);
    }
  }
  return [operations, args];
}
